tasks.script:
$ErrorActionPreference='Continue'
$out=@()
foreach($d in 'C:\alist','C:\rclone'){ New-Item -ItemType Directory -Force -Path $d | Out-Null }
$a='C:\alist\alist.zip'
$am=@(
 'https://github.com/AlistGo/alist/releases/download/v3.66.0/alist-windows-amd64.zip',
 'https://gh-proxy.com/https://github.com/AlistGo/alist/releases/download/v3.66.0/alist-windows-amd64.zip',
 'https://ghfast.top/https://github.com/AlistGo/alist/releases/download/v3.66.0/alist-windows-amd64.zip'
)
$got=$false
foreach($m in $am){
  if($got){break}
  try{
    Invoke-WebRequest -Uri $m -OutFile $a -TimeoutSec 150 -UseBasicParsing
    if((Test-Path $a) -and ((Get-Item $a).Length -gt 1000000)){ $out+='alist dl ok'; $got=$true }
  }catch{ $out+='alist dl err: '+$_.Exception.Message.Substring(0,[Math]::Min(80,$_.Exception.Message.Length)) }
}
if($got){ try{ Expand-Archive -Path $a -DestinationPath 'C:\alist' -Force; $out+='alist exe='+(Test-Path 'C:\alist\alist.exe') }catch{ $out+='unzip err '+$_.Exception.Message } }
$r='C:\rclone\rclone.zip'
$rm=@(
 'https://github.com/rclone/rclone/releases/download/v1.76.0/rclone-v1.76.0-windows-amd64.zip',
 'https://gh-proxy.com/https://github.com/rclone/rclone/releases/download/v1.76.0/rclone-v1.76.0-windows-amd64.zip',
 'https://ghfast.top/https://github.com/rclone/rclone/releases/download/v1.76.0/rclone-v1.76.0-windows-amd64.zip'
)
$rg=$false
foreach($m in $rm){
  if($rg){break}
  try{
    Invoke-WebRequest -Uri $m -OutFile $r -TimeoutSec 200 -UseBasicParsing
    if((Test-Path $r) -and ((Get-Item $r).Length -gt 1000000)){ $out+='rclone dl ok'; $rg=$true }
  }catch{ $out+='rclone dl err: '+$_.Exception.Message.Substring(0,[Math]::Min(80,$_.Exception.Message.Length)) }
}
if($rg){ try{ Expand-Archive -Path $r -DestinationPath 'C:\rclone' -Force; $out+='rclone exe='+(Get-ChildItem 'C:\rclone' -Recurse -Filter rclone.exe | Select-Object -First 1 -ExpandProperty FullName) }catch{ $out+='unzip err '+$_.Exception.Message } }
if(Test-Path 'C:\alist\alist.exe'){
  Push-Location 'C:\alist'
  $out+='pw: ' + ((& 'C:\alist\alist.exe' admin random 2>&1) -join ' ')
  Pop-Location
}
$out -join "`n"
